local phase = "new"
local function stop_timers() eq.stop_timer("settle"); eq.stop_timer("expire") end
function event_spawn(e)
  if phase ~= "new" then return end
  phase = "settling"; eq.set_timer("settle", 1000)
end
function event_combat(e)
  if phase == "ended" then return end
  stop_timers()
  if e.joined then phase = "fighting"
  else phase = "waiting"; eq.set_timer("expire", 50000) end
end
function event_timer(e)
  if phase ~= "waiting" and phase ~= "settling" then return end
  -- A queued timer must not erase a fight whose combat callback is in flight.
  if e.self:IsEngaged() then phase = "fighting"; stop_timers(); return end
  if e.timer == "settle" and phase == "settling" then
